-- conciliacion_aeda_oseda_20261127.sql
-- ============================================================================
-- Se corre UNA vez en la base de OSEDA (contable de Railway, base `railway`),
-- con un usuario que pueda escribir (app_gestion alcanza). En DBeaver:
-- «Ejecutar script» (Alt+X).
--
-- Deja el atributo AEDA («Afiliado al Gremio») como lo define la regla del
-- 27/11/2026: lo tiene quien es TITULAR en OSEDA y TITULAR ACTIVO en el padrón
-- del gremio (gestion_sindicato). Nadie más: ni familiares, ni titulares dados
-- de baja en el gremio, ni CUIL que el gremio no tiene.
--
-- La liquidación de planes no cambia por los familiares: sp_procesar_l_liquidacion
-- toma el atributo del titular y lo aplica a todo el grupo. Sí cambia
-- fiscalizacion_aeda.py (cuota por DDJJ, por persona): 9 familiares con DDJJ en
-- 2026 dejan de contar ahí. Decidido así.
--
-- Esperado al 27/11/2026 08:10:  poner 34 · sacar titulares 40 · sacar familiares 59
-- Si los números no dan eso (alguien tocó el padrón en el medio), el script NO
-- cambia nada: muestra el plan y termina con «NO APLICADO». Revisar y ajustar
-- los esperados abajo.
--
-- Respaldo: lo que se saca queda en zz_bkp_atributos_aeda_20261127.
-- Auditoría: un movimiento por persona en p_afiliados_movimientos, origen
-- SISTEMA, origen_ref «conciliacion gremio», como lo deja el ABM del sindicato.
-- ============================================================================

USE railway;

SET @esperado_poner := 34, @esperado_sacar_tit := 40, @esperado_sacar_fam := 59;
SET @usuario := 'Esteban Gabriel Salaya (conciliación AEDA)';

SET @atr := (SELECT id FROM p_afiliado_atributo WHERE rotulo = 'AEDA' ORDER BY id LIMIT 1);

-- Titulares activos en el gremio, tomados de la base sindicato el 27/11/2026.
DROP TEMPORARY TABLE IF EXISTS tmp_gremio;
CREATE TEMPORARY TABLE tmp_gremio (cuil VARCHAR(11) PRIMARY KEY);
INSERT IGNORE INTO tmp_gremio (cuil)
