-- El plan: qué tiene hoy cada afiliado de OSEDA y qué tiene que tener.
DROP TEMPORARY TABLE IF EXISTS tmp_plan_aeda;
CREATE TEMPORARY TABLE tmp_plan_aeda (
    id_afiliado INT PRIMARY KEY,
    cuil        VARCHAR(11),
    accion      ENUM('PONER','SACAR_TITULAR','SACAR_FAMILIAR')
);
INSERT INTO tmp_plan_aeda (id_afiliado, cuil, accion)
SELECT a.id_afiliado, a.cuil,
       CASE WHEN tiene = 0 THEN 'PONER'
            WHEN a.cod_parentesco = 0 THEN 'SACAR_TITULAR'
            ELSE 'SACAR_FAMILIAR' END
  FROM (SELECT a.*,
               EXISTS (SELECT 1 FROM p_atributos_por_afiliado x
                        WHERE x.id_afiliado = a.id_afiliado AND x.id_atributo = @atr) AS tiene,
               (a.cod_parentesco = 0 AND a.cuil IN (SELECT cuil FROM tmp_gremio)) AS debe
          FROM p_afiliados a) a
 WHERE a.tiene <> a.debe;

SET @poner     := (SELECT COUNT(*) FROM tmp_plan_aeda WHERE accion = 'PONER');
SET @sacar_tit := (SELECT COUNT(*) FROM tmp_plan_aeda WHERE accion = 'SACAR_TITULAR');
SET @sacar_fam := (SELECT COUNT(*) FROM tmp_plan_aeda WHERE accion = 'SACAR_FAMILIAR');
SET @ok := (@atr IS NOT NULL AND (SELECT COUNT(*) FROM tmp_gremio) = 1910
            AND @poner = @esperado_poner AND @sacar_tit = @esperado_sacar_tit
            AND @sacar_fam = @esperado_sacar_fam);

SELECT @poner AS poner, @sacar_tit AS sacar_titulares, @sacar_fam AS sacar_familiares,
       IF(@ok, 'los números dan: se aplica', 'NO dan los números: no se cambia nada') AS control;

-- Respaldo de lo que se saca (solo si se aplica). El CREATE va antes de la
-- transacción: en MySQL un CREATE TABLE confirma lo que hubiera abierto.
CREATE TABLE IF NOT EXISTS zz_bkp_atributos_aeda_20261127 LIKE p_atributos_por_afiliado;

START TRANSACTION;

INSERT INTO zz_bkp_atributos_aeda_20261127
SELECT x.* FROM p_atributos_por_afiliado x
  JOIN tmp_plan_aeda p ON p.id_afiliado = x.id_afiliado AND p.accion <> 'PONER'
 WHERE x.id_atributo = @atr AND @ok;

DELETE x FROM p_atributos_por_afiliado x
  JOIN tmp_plan_aeda p ON p.id_afiliado = x.id_afiliado AND p.accion <> 'PONER'
 WHERE x.id_atributo = @atr AND @ok;

INSERT INTO p_atributos_por_afiliado (id_atributo, id_afiliado, observaciones, usuario)
SELECT @atr, p.id_afiliado, 'Conciliación con el padrón del gremio 27/11/2026', LEFT(@usuario, 60)
  FROM tmp_plan_aeda p
 WHERE p.accion = 'PONER' AND @ok;

INSERT INTO p_afiliados_movimientos
    (id_afiliado, cuil, tipo_movimiento, origen, origen_ref, campo, campo_label,
     valor_anterior, valor_actual, usuario, observaciones)
SELECT p.id_afiliado, p.cuil, 'MODIFICACION', 'SISTEMA', 'conciliacion gremio', 'atributo', 'Atributo',
       IF(p.accion = 'PONER', NULL, 'AEDA'), IF(p.accion = 'PONER', 'AEDA', NULL), LEFT(@usuario, 80),
       CASE p.accion
            WHEN 'PONER' THEN 'Se asignó el atributo «AEDA»: titular activo en el padrón del gremio (conciliación 27/11/2026)'
            WHEN 'SACAR_TITULAR' THEN 'Se quitó el atributo «AEDA»: no es titular activo en el padrón del gremio (conciliación 27/11/2026)'
            ELSE 'Se quitó el atributo «AEDA»: es familiar, y el atributo va solo en el titular (conciliación 27/11/2026)' END
  FROM tmp_plan_aeda p
 WHERE @ok;

COMMIT;

-- Detalle de lo que se hizo (o de lo que se hubiera hecho, si no dieron los números).
SELECT p.accion, p.cuil, TRIM(CONCAT(IFNULL(a.apellido, ''), ' ', IFNULL(a.nombre, ''))) AS afiliado,
       a.cod_parentesco, a.activo, a.fecha_baja,
       IF(@ok, 'aplicado', 'NO APLICADO') AS estado
  FROM tmp_plan_aeda p JOIN p_afiliados a ON a.id_afiliado = p.id_afiliado
 ORDER BY p.accion, afiliado;

-- Control final: después de aplicar tiene que dar 0 familiares y 1229 titulares con AEDA.
SELECT SUM(a.cod_parentesco = 0) AS titulares_con_aeda, SUM(a.cod_parentesco <> 0) AS familiares_con_aeda
  FROM p_atributos_por_afiliado x JOIN p_afiliados a ON a.id_afiliado = x.id_afiliado
 WHERE x.id_atributo = @atr;

DROP TEMPORARY TABLE IF EXISTS tmp_plan_aeda;
DROP TEMPORARY TABLE IF EXISTS tmp_gremio;
